using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var tools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When the user gives you a topic:
        1. Search the web for relevant information using the search tool (make 2-3 searches with different queries).
        2. Save important findings as notes using the note-taking tool.
        3. After gathering enough information, provide a well-structured summary of your findings.
        Always cite the sources (titles and URLs) you found.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and summarizing findings.",
    tools: [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.SaveNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ]);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (GPT-4o)     ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    tools.ClearNotes();
    Console.WriteLine($"\nResearching: {topic}\n");

    try
    {
        var session = await agent.CreateSessionAsync();
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        });

        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            session,
            runOptions))
        {
            Console.Write(update.Text);
        }

        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\nError: {ex.Message}");
    }
}

Console.WriteLine("\nGoodbye!");

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new();
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a given query. Returns a list of search result titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await s_httpClient.GetFromJsonAsync<JsonElement>(url, cancellationToken);

            var results = new List<string>();

            // Extract the abstract (main result)
            var abstractText = response.GetProperty("Abstract").GetString();
            var abstractUrl = response.GetProperty("AbstractURL").GetString();
            var abstractSource = response.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}\nURL: {abstractUrl}");
            }

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrEmpty(text))
                    {
                        results.Add($"- {text}\n  URL: {firstUrl}");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try a different search query.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save an important note or finding from the research. Use this to record key facts, insights, or source information.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return string.Join("\n---\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    public void ClearNotes() => _notes.Clear();
}

